def solution(input_str):
    n, m = map(int, input_str.split('\n')[0].split())
    offers = []
    for i in range(1, m + 1):
        l, r = map(int, input_str.split('\n')[i].split())
        offers.append((l, r))

    def simulate(x):
        occupied = set()
        total_days = 0
        for l, r in offers:
            length = r - l + 1
            if length >= x:
                overlap = False
                for day in range(l, r + 1):
                    if day in occupied:
                        overlap = True
                        break
                if not overlap:
                    for day in range(l, r + 1):
                        occupied.add(day)
                        total_days += 1
        return total_days

    results = [str(simulate(x)) for x in range(1, n + 1)]
    return '\n'.join(results) + '\n'

