def solution(input_string):
    lines = input_string.strip().split('\n')

    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    edges = []
    for i in range(m):
        u, v, w = map(int, lines[2 + i].split())
        edges.append((u, v, w, i + 1))  # i+1 for 1-based indexing

    def build_graph(exclude_idxs=None):
        """Build adjacency list, excluding edges with given indices"""
        if exclude_idxs is None:
            exclude_idxs = set()
        adj = defaultdict(list)
        for idx, (u, v, w, edge_idx) in enumerate(edges):
            if idx + 1 not in exclude_idxs:
                adj[u].append((v, w))
                adj[v].append((u, w))
        return adj

    def is_connected(adj, start, end):
        """Check if start can reach end using BFS"""
        if start == end:
            return True
        visited = {start}
        queue = [start]
        while queue:
            curr = queue.pop(0)
            for neighbor, _ in adj[curr]:
                if neighbor not in visited:
                    if neighbor == end:
                        return True
                    visited.add(neighbor)
                    queue.append(neighbor)
        return False

    def dfs_path(adj, start, end, target_node=None, found_path=None):
        """DFS to find a path from start to end and record which edges are on the path"""
        visited = set()
        path_edges = []

        def dfs(u, path):
            if u == end or (target_node and u == target_node):
                return True

            if u in visited:
                return False

            visited.add(u)
            for v, _ in adj.get(u, []):
                if v not in visited:
                    edge_exists = False
                    for i, (eu, ev, ew, idx) in enumerate(edges):
                        if i+1 in path and (u == eu and v == ev) or (u == ev and v == eu):
                            edge_exists = True
                            break

                    if edge_exists:
                        continue

                    if dfs(v, path + [(i+1, u, v)]):
                        return True

        if dfs(start, []):
            return True
        return False

    # Check if s and t are already disconnected
    adj = build_graph()
    if not is_connected(adj, s, t):
        return "0\n0\n"

    # Try removing 1 edge
    for i, (_, _, _, edge_idx) in enumerate(edges):
        exclude = {i + 1}
        adj = build_graph(exclude)
        if not is_connected(adj, s, t):
            return f"{edges[i][2]}\n1\n{edge_idx}"

    # Try removing 2 edges
    best_cost = float('inf')
    best_edges = []

    for i, (u1, v1, w1, idx1) in enumerate(edges):
        exclude1 = {i + 1}
        adj1 = build_graph(exclude1)

        # For BFS, compute next_hop to check if excluding one more edge disconnects s and t
        # But this is slow, so instead we use a clever approach:
        # Check pairs but optimize by focusing on vertices

        # BFS to find all vertices that can reach t with current # edges
        # Actually, let's just try BFS to get shortest path from s after removing first edge
        # Then second edge can be any edge on that path or any edge adjacent to it

        # Strategy: After removing edge 1, find a path from s to t. 
        # Then remove the most expensive edge on that path -- wait, we want min cost
        # So we remove the cheapest edge on the path

        if not is_connected(adj1, s, t):
            continue

        # Get all paths of length 2 from s: s -> v -> ... -> t
        # For each such edge (s,v), try removing it along with edge1
        path_found = False
        for v, _ in adj1.get(s, []):
            # Try removing edge from s to v
            edge2_on_path = False
            for j, (_, _, _, idx2) in enumerate(edges):
                if idx1 == idx2:
                    continue
                if (s == edges[j][0] and v == edges[j][1]) or (s == edges[j][1] and v == edges[j][0]):
                    edge2_on_path = True
                    break

            if edge2_on_path:
                exclude2 = exclude1 | {idx2}
                adj2 = build_graph(exclude2)
                if not is_connected(adj2, s, t):
                    return f"{w1 + edges[j][2]}\n2\n{idx1} {idx2}"

        # Also need to consider edge1 and a completely different edge
        # BFS from s in adj1, stop when we hit all neighbors of t
        # Then try all edges on those shortest paths

        from collections import deque
        dist = {s: 0}
        queue = deque([s])
        nodes_reachable = {s}

        while queue:
            curr = queue.popleft()
            if curr == t:
                path_found = True
                break
            for neighbor, _ in adj1.get(curr, []):
                if neighbor not in dist:
                    dist[neighbor] = dist[curr] + 1
                    nodes_reachable.add(neighbor)
                    queue.append(neighbor)

        if not path_found:
            continue

        # Find edges that are on some path but weren't the first edge we tried
        for j, (_, _, _, idx2) in enumerate(edges):
            if idx2 == idx1:
                continue

            exclude2 = exclude1 | {idx2}
            adj2 = build_graph(exclude2)

            if not is_connected(adj2, s, t):
                return f"{w1 + edges[j][2]}\n2\n{idx1} {idx2}"

    return "-1"


