def solution(input_string):
    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    edges = []

    for i in range(1, m + 1):
        u, v, w = map(int, lines[i].split())
        edges.append((u, v, w, i))
        adj[u].append((v, w, i))
        adj[v].append((u, w, i))

    start_node = int(lines[m + 1])

    # Dijkstra's algorithm
    import heapq
    dist = [float('inf')] * (n + 1)
    dist[start_node] = 0
    pq = [(0, start_node)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w, idx in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    # Select minimum weight edges for the shortest path tree
    total_weight = 0
    selected_edges = []

    for v in range(1, n + 1):
        if v == start_node:
            continue
        if dist[v] == float('inf'):
            continue

        best_edge_idx = None
        best_w = float('inf')

        for u, w, idx in adj[v]:
            if dist[u] != float('inf') and dist[u] + w == dist[v]:
                if w < best_w:
                    best_w = w
                    best_edge_idx = idx

        if best_edge_idx is not None:
            total_weight += best_w
            selected_edges.append(best_edge_idx)

    result_lines = [str(total_weight), ' '.join(map(str, selected_edges))]
    return '\n'.join(result_lines)


