        return all(x == 0 for x in a)

    # Check if GP using cross-multiplication to avoid division
    # For GP, a[i] * a[0] == a[i-1] * a[1] should hold for all valid i
    for i in range(1, n):
        if a[i] * a[0] != a[i-1] * a[1]:
            return False

    return True


