class Solution:
    def solution(self, input_str):
        lines = input_str.strip().split('\n')
        if not lines:
            return ''

        first_line = lines[0].split()
        n = int(first_line[0])
        m = int(first_line[1])

        edges = []
        for i in range(1, m + 1):
            parts = lines[i].split()
            u = int(parts[0])
            v = int(parts[1])
            w = int(parts[2])
            edges.append((u, v, w, i - 1))

        if m == n - 1:
            return ''

        # Union-Find for Kruskal's MST
        parent = list(range(n + 1))

        def find(x):
            root = x
            while parent[root] != root:
                root = parent[root]
            # Path compression
            curr = x
            while curr != root:
                nxt = parent[curr]
                parent[curr] = root
                curr = nxt
            return root

        def union(x, y):
            px, py = find(x), find(y)
            return px != py

        # Sort edges by weight
        sorted_edges = sorted(edges, key=lambda x: x[2])

        mst_adj = [[] for _ in range(n + 1)]
        mst_edge_info = {}
        in_mst = [False] * m

        for u, v, w, idx in sorted_edges:
            if find(u) != find(v):
                union(u, v)
                mst_adj[u].append(v)
                mst_adj[v].append(u)
                mst_edge_info[(min(u, v), max(u, v))] = w
                in_mst[idx] = True

        # If not connected (shouldn't happen per problem)
        if sum(1 for x in in_mst if x) < n - 1:
            return ''

        # Process non-MST edges using binary lifting on MST
        # Use iterative DFS for depth/parent setup
        depth = [0] * (n + 1)
        up = [[0] * (n + 1) for _ in range(21)]
        max_edge = [[-1] * (n + 1) for _ in range(21)]
        visited = [False] * (n + 1)

        stack = [1]
        visited[1] = True
        depth[1] = 0
        up[0][1] = 1  # Root's parent is itself
        max_edge[0][1] = -1

        # First DFS to set depth, parent, and max_edge
        for node in reversed(range(1, n + 1)):
            for neighbor in mst_adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    depth[neighbor] = depth[node] + 1
                    up[0][neighbor] = node
                    key = (min(node, neighbor), max(node, neighbor))
                    max_edge[0][neighbor] = mst_edge_info[key]

        # Binary lifting preprocessing
        for j in range(1, 21):
            for i in range(1, n + 1):
                parent_node = up[j - 1][i]
                if parent_node != 0:
                    up[j][i] = up[j - 1][parent_node]
                    max_edge[j][i] = max(max_edge[j - 1][i], max_edge[j - 1][parent_node])
                else:
                    up[j][i] = i
                    max_edge[j][i] = max_edge[j - 1][i]

        def get_lca(u, v):
            if depth[u] < depth[v]:
                u, v = v, u

            diff = depth[u] - depth[v]
            for j in range(21):
                if diff & (1 << j):
                    u = up[j][u]

            if u == v:
                return u

            for j in range(20, -1, -1):
                if up[j][u] != up[j][v]:
                    u = up[j][u]
                    v = up[j][v]

            return up[0][u]

        def get_max_edge_on_path_to_ancestor(node, ancestor_depth):
            path_max = -1
            diff = depth[node] - ancestor_depth
            for j in range(21):
                if diff & (1 << j):
                    path_max = max(path_max, max_edge[j][node])
                    node = up[j][node]
            return path_max

        results = []
        for u, v, w, idx in edges:
            if not in_mst[idx]:
                lca = get_lca(u, v)
                max_w = -1
                if depth[u] > depth[lca]:
                    max_w = max(max_w, get_max_edge_on_path_to_ancestor(u, depth[lca]))
                if depth[v] > depth[lca]:
                    max_w = max(max_w, get_max_edge_on_path_to_ancestor(v, depth[lca]))
                results.append((idx, max_w))

        results.sort(key=lambda x: x[0])

        output_lines = [str(w) for _, w in results]
        return '\n'.join(output_lines) + '\n' if output_lines else ''


