    def dfs(u, depth):
        nonlocal found_cycle
        visited[u] = True
        on_stack[u] = True
        path.append(u)

        for v in adj[u]:
            if not visited[v]:
                parent[v] = u
                if dfs(v, depth + 1):
                    return True
            elif on_stack[v] and v != parent[u]:
                # Found a cycle
                cycle = []
                curr = v
                start_depth = depth + 1
                while curr != v:
                    cycle.append(curr)
                    curr = parent[curr] if curr != -1 else path[start_depth - 1] if start_depth <= len(path) else path[start_depth - start_depth % len(path)]
                    start_depth -= 1 if curr != v else 0
                cycle.append(v)
