    if max_deg >= k:
        # Remove high degree nodes iteratively
        changed = True
        while changed:
            changed = False
            for i in range(1, n + 1):
                if in_degree[i] >= k:
                    # This node can reduce its neighbors' degrees
                    for v in adj[i]:
                        in_degree[v] -= 1
            for i in range(1, n + 1):
