import random
import sys

def is_prime(n):
    """Miller-Rabin primality test"""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0:
        return False

    # Write n-1 as 2^r * d
    d = n - 1
    r = 0
    while d % 2 == 0:
        d //= 2
        r += 1

    def check(a):
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            return True
        for _ in range(r - 1):
            x = (x * x) % n
            if x == n - 1:
                return True
        return False

    # Test with several bases
    for _ in range(20):
        a = random.randint(2, n - 1)
        if not check(a):
            return False
    return True

def factorize(n):
    """Return list of prime factors"""
    factors = []
    d = 2
    while d * d <= n:
        if n % d == 0:
            factors.append(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def is_primitive_root(p, b, factors):
    """Check if b is primitive root modulo p"""
    for q in factors:
        if pow(b, (p - 1) // q, p) == 1:
            return False
    return True

