    # Check if n + 1 is prime
    if not is_prime(p):
        return "-1"

    # Get prime factors of p-1 (which is n)
    factors = factorize(p - 1)

    # Maximum possible base is min(x-1, p-2) since b < p and b < x
    max_b = min(x - 1, p - 2)

    if max_b < 2:
        return "-1"

    # Try to find primitive root
    # Strategy: try random first, then deterministic search if needed
    found = False
    result = -1

    # First try random sampling for efficiency
    for _ in range(100):
        b = random.randint(2, max_b)
        if is_primitive_root(p, b, factors):
            result = b
            found = True
            break

    if not found:
        # Fallback: search from largest valid base downward
        for b in range(max_b, 1, -1):
            if is_primitive_root(p, b, factors):
                result = b
                found = True
                break

    return str(result) if found else "-1"

