import sys

def solution(input_str):
    input_data = input_str.strip().split()
    if len(input_data) < 2:
        return '0\n'

    l, r = int(input_data[0]), int(input_data[1])

    # According to number theory:
    # A prime p is expressible as a sum of two positive squares iff p = 2 or p ≡ 1 (mod 4)
    # 2 = 1² + 1² (both positive)
    # Primes ≡ 1 (mod 4) can be uniquely written as a² + b² with a, b > 0

    count = 0

    # Check if 2 is in range [l, r]
    if l <= 2 and r >= 2:
        count += 1

    # Segmented sieve for primes in [max(l, 3), r]
    # Need primes up to sqrt(r) for sieving
    limit = int(r**0.5) + 1
    small_sieve = [True] * (limit + 1)
    small_sieve[0] = small_sieve[1] = False

    for i in range(2, int(limit**0.5) + 1):
        if small_sieve[i]:
            for j in range(i*i, limit + 1, i):
                small_sieve[j] = False

    base_primes = [i for i in range(2, limit + 1) if small_sieve[i]]

    # Only use primes >= 3 for sieving (already handled 2)
    base_primes = [p for p in base_primes if p >= 3]

    start = max(l, 3)
    block_size = 100000  # Process in blocks to save memory

    while start <= r:
        end = min(r, start + block_size - 1)
        block_len = end - start + 1

        is_prime = [True] * block_len

        for p in base_primes:
            if p*p > end:
                break

            # Find first multiple of p >= start
            first_mult = ((start + p - 1) // p) * p
            # But we must start from max(first_mult, p*p) to avoid marking p itself
            if first_mult < p*p:
                first_mult = p*p

            if first_mult > end:
                continue

            for j in range(first_mult, end + 1, p):
                is_prime[j - start] = False

        # Count primes in this block that satisfy p ≡ 1 (mod 4)
        for i in range(block_len):
            num = start + i
            if is_prime[i] and (num % 4 == 1):
                count += 1

        start += block_size

    return str(count) + '\n'


