        """
        Count valid ways to complete from (row_idx, start_col)
        used_values: values already placed in current row
        prev_row: the previous row's values (for column constraints)
        """
        if row_idx == n:
            return 1

        if start_col == n:
            return False  # Should not reach here when called properly

        row = a[row_idx] if row_idx < n else None
        if row is None:
            return 1

