            if val in used_values:
                continue
            if row_idx > 0 and val == prev_row[start_col]:
                continue

            new_used = used_values | {val}
            if row_idx < n - 1:
                count = count_valid(row_idx + 1, 0, new_used, row)
                count = count % MOD
            else:
                count = count + 1 if start_col == n else 0

        return count % MOD

