    first_line = lines[0].split()
    n, m, k = int(first_line[0]), int(first_line[1]), int(first_line[2])

    # Handle special case: n = 1 (only capital city, no roads needed)
    if n == 1:
        return "0\n\n"

    edges = []

    # Parse edges (1-indexed lines for output)
    for i in range(1, len(lines)):
        line = lines[i].strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) >= 3:
            u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
            # Check if edge is connected to capital (city 1)
            is_capital = (u == 1 or v == 1)
            edges.append((w, is_capital, u, v, i))

    # Sort edges by weight
    edges.sort(key=lambda x: x[0])

    # Union-Find data structure
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            parent[px] = py
        elif rank[px] > rank[py]:
            parent[py] = px
        else:
            parent[px] = py
            rank[py] += 1
        return True

    result = []

    # Kruskal's algorithm with capital edge constraint
    for w, is_capital, u, v, idx in edges:
        if union(u, v):
            result.append(idx)
            if len(result) == n - 1:
                break

    # Check if all cities are connected
    if len(result) < n - 1:
        return "-1\n"

    # Verify connectivity
    root = find(1)
    for i in range(2, n + 1):
        if find(i) != root:
            return "-1\n"

    # Output result
    return str(len(result)) + "\n" + " ".join(map(str, result)) + "\n"

def solution(input_str):
    def complement(s):
        return ''.join('1' if c == '0' else '0' for c in s)

    def reverse(s):
        return s[::-1]

    def canonical(s):
        forms = [s, reverse(s), complement(s), complement(reverse(s))]
        return min(forms)

    n, k_str = input_str.strip().split()
    k = int(k_str)

    total_strings = 1 << n
    num_canonical = 0

    # Count canonical strings by generating in a way to avoid duplicates
    # We generate strings in lexicographical order and track which are canonical
    seen_canonical = set()

    for i in range(total_strings):
        # Convert integer to binary string of length n
        bits = format(i, f'0{n}b')
        # Only process each string once - we count canonical forms
        cls_rep = canonical(bits)
        if cls_rep not in seen_canonical:
            seen_canonical.add(cls_rep)
            num_canonical += 1
            if num_canonical == k:
                return bits + '\n'

    return '-1\n'

