def solution(input_str):
    lines = input_str.strip().split('\n')

    if not lines:
        return "Lillebror\n"

    # Parse grid into 2D array
    grid = []
    for line in lines:
        parts = line.strip().split()
        grid.append(parts)

    # Verify total is 19 cells
    total = sum(len(row) for row in grid)

    # Map (r, c) to linear index 0-18
    def cell_index(r, c):
        return sum(len(grid[i]) for i in range(r)) + c

    # Collect all chocolate positions
    chocolates = set()
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == 'O':
                chocolates.add((r, c))

    # Create state as bitmask
    state = 0
    for (r, c) in chocolates:
        state |= (1 << cell_index(r, c))

    from functools import lru_cache

    # Directions: (dr, dc) for the 3 line directions
    # Horizontal: (0, 1) with all cells in row
    # Diagonal down-right: (1, 1) 
    # Diagonal down-left: (1, 0)

    @lru_cache(maxsize=None)
    def grundy(s):
        reachable = set()

        if s == 0:
            return 0

        # Horizontal lines (same row)
        for r in range(len(grid)):
            cols = list(range(len(grid[r])))
            i = 0
            while i < len(cols):
                j = i
                all_choc = True
                while j < len(cols):
                    if not ((s >> cell_index(r, j)) & 1):
                        all_choc = False
                        break
                    j += 1

                if all_choc and j > i:
                    mask = 0
                    for k in range(i, j):
                        mask |= (1 << cell_index(r, k))
                    reachable.add(s & ~mask)
                i += 1

        # Diagonal down-left: (1, 0) - same column index
        for r in range(len(grid)):
            for c in range(len(grid[r])):
                if not ((s >> cell_index(r, c)) & 1):
                    continue

                # Go down-left
                r0, c0 = r, c
                path = []
                i = r0
                while i < len(grid) and c0 < len(grid[i]):
                    path.append((i, c0))
                    i += 1

                # Find maximal consecutive segment starting from (r,c)
                j = r0
                while j < i and c0 < len(grid[j]):
                    if not ((s >> cell_index(j, c0)) & 1):
                        break
                    j += 1

                if j - r0 > 0:
                    mask = 0
                    for k in range(r0, j):
                        mask |= (1 << cell_index(k, c0))
                    reachable.add(s & ~mask)

        # Diagonal down-right: (1, 1) - increments column with row
        for r in range(len(grid)):
            for c in range(len(grid[r])):
                if not ((s >> cell_index(r, c)) & 1):
                    continue

                # Go down-right
                r0, c0 = r, c
                path = []
                i = 0
                while i < len(grid) and (r0 + i) < len(grid) and (c0 + i) < len(grid[r0 + i]):
                    path.append((r0 + i, c0 + i))
                    i += 1

                # Find maximal consecutive segment starting from (r,c)
                j = 0
                while j < i:
                    if not ((s >> cell_index(r0 + j, c0 + j)) & 1):
                        break
                    j += 1

                if j > 0:
                    mask = 0
                    for k in range(j):
                        mask |= (1 << cell_index(r0 + k, c0 + k))
                    reachable.add(s & ~mask)

        # Compute mex
        mex = 0
        while mex in reachable:
            mex += 1
        return mex

    if grundy(state) > 0:
        return "Karlsson\n"
    else:
        return "Lillebror\n"


