def solution(input_data):
    data = input_data.strip().split('\n')
    n, m = map(int, data[0].split())

    graph = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, data[i].split())
        graph[u].append(v)

    # All pairs shortest paths using BFS
    dist = [[0] * (n + 1) for _ in range(n + 1)]
    for start in range(1, n + 1):
        d = [-1] * (n + 1)
        d[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in graph[u]:
                if d[v] == -1:
                    d[v] = d[u] + 1
                    queue.append(v)
        dist[start] = d

    # Find 4 distinct cities with maximum total distance
    max_distance = -1
    best_path = []

    # Try all combinations of 4 cities and all orderings
    # Since n <= 3000, we can optimize by limiting our search
    for a in range(1, n + 1):
        for b in range(1, n + 1):
            if a == b or dist[a][b] == -1:
                continue
            for c in range(1, n + 1):
                if c == a or c == b or dist[b][c] == -1:
                    continue
                for d in range(1, n + 1):
                    if d == a or d == b or d == c or dist[c][d] == -1:
                        continue

                    total = dist[a][b] + dist[b][c] + dist[c][d]
                    if total > max_distance:
                        max_distance = total
                        best_path = [a, b, c, d]

    return ' '.join(map(str, best_path))

