def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "EMPTY SET"
    n = int(lines[0])
    queries = lines[1:]

    # Track all added lines with their original index (1-based)
    all_lines = {}  # line_idx -> (a, b)
    active_lines = {}  # line_idx -> True

    # Add a line (a, b) at query number i
    def add_line(i, a, b):
        all_lines[i] = (a, b)
        active_lines[i] = True

    # Remove a line at query number i
    def remove_line(i):
        if i in active_lines:
            del active_lines[i]

    def get_max_pair(q):
        if not active_lines:
            return float('-inf')

        max_val = float('-inf')
        for i in active_lines:
            a, b = all_lines[i]
            val = a * q + b
            if val > max_val:
                max_val = val
        return max_val

    result = []

    # Use query index counter
    query_idx = 1

    for query in queries:
        parts = list(map(int, query.split()))
        t = parts[0]

        if t == 1:
            # Add pair: 1 a b
            a, b = parts[1], parts[2]
            add_line(query_idx, a, b)
        elif t == 2:
            # Remove query number i (1-based)
            i = parts[1]
            remove_line(i)
        elif t == 3:
            # Query: 3 q
            q = parts[1]
            if not active_lines:
                result.append("EMPTY SET")
            else:
                max_val = get_max_pair(q)
                result.append(str(max_val))

        query_idx += 1

    return '\n'.join(result)

