    def get_matrix_inverse_col(matrix: List[List[int]], col_idx: int) -> List[int]:
        col = [matrix[row][col_idx] for row in range(n)]
        inverse = [0] * n
        for i, val in enumerate(col):
            inverse[val - 1] = i + 1
        return inverse

    def create_matrix_inverse(matrix: List[List[int]], col_offset: int, row_offset: int) -> List[List[int]]:
        if row_offset == n and col_offset == n:
            return matrix  # Identity, already shifted to original

        # Create inverse based on actual positions
        inv_matrix = [[0] * n for _ in range(n)]
        for row in range(n):
            true_row_idx = ((row + row_offset - 1) % n) + 1
            true_row = matrix[true_row_idx - 1]
            inv_matrix[row][0] = 0  # Internal position row
            for col in range(n):
                true_col_idx = ((col + col_offset - 1) % n) + 1
                inv_matrix[row][col] = true_row[(true_col_idx - 1 - 1 + n) % n] + 1
        return inv_matrix

    def undo_inversion(matrix: List[int], row_idx: int, col_idx: int) -> int:
        if row_idx >= 1:
            return matrix[row_idx + col_idx - 1]
        else:
            return 0

    def reverse_cyclic_shift_right(matrix, n, m):
        for i in range(n):
            temp = matrix[i][0]
            for j in range(n-1):
                matrix[i][j] = matrix[i][j+1]
            matrix[i][n-1] = temp

    def reverse_cyclic_shift_left(matrix, n, m):
        for i in range(n):
            temp = matrix[i][0]
            for j in range(n-1):
                matrix[i][j] = matrix[i][j+1]
            matrix[i][n-1] = temp

    def reverse_cyclic_shift_down(matrix, n, m):
        for j in range(n):
            temp = matrix[0][j]
            for i in range(n-1):
                matrix[i+1][j] = matrix[i][j]
            matrix[0][j] = temp

    def reverse_cyclic_shift_up(matrix, n, m):
        for j in range(n):
            temp = matrix[n-1][j]
            for i in range(n-1, 0, -1):
                matrix[i][j] = matrix[i-1][j]
            matrix[0][j] = temp

