def binomial(n, k, MOD):
    if k < 0 or k > n:
        return 0
    num = 1
    den = 1
    for i in range(k):
        num = (num * (n - i)) % MOD
        den = (den * (i + 1)) % MOD
    return (num * pow(den, MOD - 2, MOD)) % MOD

