def solution(input_str):
    n, k, m = map(int, input_str.strip().split())
    MOD = 10**9 + 7

    # If k == 1, we just need to choose a starting planet (n ways)
    if k == 1:
        return str(n % MOD)

    # If k > n, we can't visit k distinct planets (shouldn't happen per constraints)
    if k > n:
        return "0"

    # We'll use memoization based on (visited_mask, current_pos, planets_left)
    # But since n can be up to 10^5, we need a smarter approach for small k

    # Since k is small (<= 12), we can think about this problem more carefully
    # We're looking for sequences p_1, p_2, ..., p_k where:
    # - All p_i are in [1, n]
    # - All p_i are distinct
    # - For i > 1: p_i <= p_{i-1} + m

    # Key insight: For small k, we can use DP with bitmask where mask represents subset of visited planets
    # However, for large n, we need to be clever. Let's observe:
    # When m is small, the choices at each step are limited.

    # For small k, we can enumerate all possible sequences by tracking:
    # - current position
    # - set of visited planets (using set for simplicity since k is small)

    from functools import lru_cache

    # Actually, let's think differently. For each starting planet, count paths of length k.
    # Since k is small, we can use DFS with pruning.

    def solve_with_start(start_pos, depth, visited):
        if depth == k:
            return 1

        count = 0
        # Try all possible next positions: 1 to start_pos + m
        for next_pos in range(1, start_pos + m + 1):
            if next_pos not in visited and next_pos <= n:
                visited.add(next_pos)
                count = (count + solve_with_start(next_pos, depth + 1, visited)) % MOD
                visited.remove(next_pos)

        return count

    total = 0
    visited = set()

    for start_pos in range(1, n + 1):
        visited.add(start_pos)
        total = (total + solve_with_start(start_pos, 1, visited)) % MOD
        visited.remove(start_pos)

