def nCr(n, r):
    """Calculate nCr modulo MOD."""
    if r < 0 or r > n:
        return 0
    num = 1
    den = 1
    for i in range(r):
        num = (num * (n - i)) % MOD
        den = (den * (i + 1)) % MOD
    return num * pow(den, MOD - 2, MOD) % MOD

