def solution(input_str):
    MOD = 10**9 + 7

    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    def square_free_part(x):
        result = x
        i = 2
        while i * i <= result:
            while result % (i * i) == 0:
                result //= (i * i)
                i = 0
            i += 1
        while i * i <= result:
            while result % (i * i) == 0:
                result //= (i * i)
            i += 1
        return result

    groups = {}
    for x in a:
        sf = 1
        temp = x
        i = 2
        while i * i <= temp:
            while temp % (i * i) == 0:
                temp //= (i * i)
            i += 1
        sf = sf * square_free_part_fix(temp)
        groups.setdefault(sf, []).append(x)

    def square_free_part_fix(x):
        result = x
        i = 2
        while i * i <= result:
            while result % (i * i) == 0:
                result //= (i * i)
            i += 1
        return result

    def square_free_part_v2(x):
        result = 1
        temp = x
        i = 2
        while i * i <= temp:
            cnt = 0
            while temp % i == 0:
                cnt += 1
                temp //= i
            if cnt % 2 == 1:
                result *= i
            i += 1
        if temp > 1:
            result *= temp
        return result

    groups = {}
    for x in a:
        sf = square_free_part_v2(x)
        groups.setdefault(sf, []).append(x)

    group_sizes = [len(v) for v in groups.values()]
    if sum(group_sizes) != n:
        return '0'

    if len(group_sizes) == 0:
        return '0'
    if len(group_sizes) == 1 and group_sizes[0] > 1:
        return '0'
    if len(group_sizes) == 1 and group_sizes[0] == 1:
        return '1'

    fact = [1] * (n + 1)
    inv = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n - 1, -1, -1):
        inv[i] = inv[i + 1] * (i + 1) % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv[r] % MOD * inv[n - r] % MOD

    dp = [0] * (n + 1)
    dp[0] = 1
    total = 0

    for size in group_sizes:
        new_dp = [0] * (n + 1)
        for i in range(total + 1):
            for j in range(min(total + 1, size)):
                if j == 0:
                    new_dp[i + j] = (new_dp[i + j] + dp[i] * nCr(i, 0)) % MOD
                else:
                    new_dp[i + j] = (new_dp[i + j] + dp[i] * nCr(i + j - 1, j - 1)) % MOD

        total += size
        dp = new_dp

    return str(dp[total])

def solution(input_string):
    lines = input_string.strip().split('\n')
    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    edges = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        a, b = int(parts[0]), int(parts[1])
        # Normalize so a < b
        if a > b:
            a, b = b, a
        edges.append((a, b))

    def cross(e1, e2):
        """Check if two edges cross on the ring"""
        a1, b1 = e1
        a2, b2 = e2

        # If edges share any endpoint, they don't cross
        if a1 == a2 or a1 == b2 or b1 == a2 or b1 == b2:
            return False

        # Two edges cross if exactly one of the second edge's endpoints
        # falls in the interval (a1, b1) going clockwise from a1 to b1
        c_in = (a1 <= a2 < b1)
        d_in = (a1 <= b2 < b1)

        return c_in != d_in

    # Build intersection graph
    adj = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if cross(edges[i], edges[j]):
                adj[i].append(j)
                adj[j].append(i)

    # Check if graph is bipartite using iterative BFS
