    for i in range(2, 2 + q):
        if i < len(lines):
            p, w = map(int, lines[i].split())
            special[p] = w

    # Edge case: single pollywog on single stone, no movement needed
    if x == 1 and n == 1:
        return "0\n"

    # Target position for the leftmost pollywog
    target_pos = n - x + 1

    if target_pos <= 1:
        return "0\n"

    INF = float('inf')

    # dp[i] = minimum cost for leftmost pollywog to reach position i
    dp = {}
    dp[1] = 0

    # Compute DP
