    scc_ids = [-1] * (n + 1)
    stack = []
    on_stack = [False] * (n + 1)
    timer = 0
    scc_count = 0

    def tarjan(u):
        nonlocal timer, scc_count
        ids[u] = low[u] = timer
        timer += 1
        stack.append(u)
        on_stack[u] = True

        for v, _ in adj[u]:
            if ids[v] == -1:
                tarjan(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], ids[v])

        if low[u] == ids[u]:
            while stack:
                w = stack.pop()
                on_stack[w] = False
                scc_ids[w] = scc_count
