def solution(input_str):
    n, m = map(int, input_str.strip().split())
    MOD = 1000000007

    if m < 2 or n < 1:
        return "0\n"

    # up[k][l][r] = number of expanding sequences of k rows reaching interval [l, r]
    # down[k][l][r] = number of contracting sequences of k rows starting at interval [l, r]

    up = [[[0] * (m + 1) for _ in range(m + 1)] for __ in range(n + 1)]
    down = [[[0] * (m + 1) for _ in range(m + 1)] for __ in range(n + 1)]

    # Base case: k=1, every valid interval has 1 way
    for l in range(1, m):
        for r in range(l + 1, m + 1):
            up[1][l][r] = 1
            down[1][l][r] = 1

    # Precompute factorials for combinations
    MAX = n + 1
    fact = [1] * MAX
    inv = [1] * MAX

    for i in range(1, MAX):
        fact[i] = (fact[i-1] * i) % MOD

    inv[MAX-1] = pow(fact[MAX-1], MOD - 2, MOD)
    for i in range(MAX - 2, -1, -1):
        inv[i] = (inv[i+1] * (i + 1)) % MOD

    def C(a, b):
        if b < 0 or b > a:
            return 0
        return fact[a] * inv[b] % MOD * inv[a-b] % MOD

    # Compute up[k] for k from 2 to n
    for k in range(2, n + 1):
        # 2D prefix sum of up[k-1]
        S = [[0] * (m + 1) for _ in range(m + 1)]
        for i in range(1, m):
            for j in range(1, m + 1):
                S[i][j] = (S[i-1][j] + S[i][j-1] - S[i-1][j-1] + up[k-1][i][j]) % MOD

        for l_val in range(1, m):
            for r_val in range(l_val + 1, m + 1):
                # sum up[k-1][i][j] where i >= l_val, j <= r_val, i < j
                total = 0
                for i in range(l_val, m):
                    max_j = min(r_val - 1, i - 1)
                    if max_j >= 1:
                        s1 = S[i][max_j]
                        s2 = (S[i-1][max_j] + MOD) % MOD
                        total = (total + s1 - s2 + MOD) % MOD
                up[k][l_val][r_val] = total

    # Compute down[k] for k from 2 to n
    for k in range(2, n + 1):
        # 2D prefix sum of down[k-1]
        S = [[0] * (m + 1) for _ in range(m + 1)]
        for i in range(1, m):
            for j in range(1, m + 1):
                S[i][j] = (S[i-1][j] + S[i][j-1] - S[i-1][j-1] + down[k-1][i][j]) % MOD

        for l_val in range(1, m):
            for r_val in range(l_val + 1, m + 1):
                # sum down[k-1][i][j] where i <= l_val, j >= r_val, i < j
                total = 0
                for i in range(1, l_val + 1):
                    min_j = max(r_val, i + 1)
                    if min_j <= m:
                        s1 = S[m-1][min_j]
                        s2 = (S[i-1][min_j] + MOD) % MOD
                        total = (total + s1 - s2 + MOD) % MOD
                down[k][l_val][r_val] = total

    # Calculate answer: sum over all intervals (l, r) and split point
    ans = 0
    for l in range(1, m):
        for r in range(l + 1, m + 1):
            # sum over possible split points k (rows in expanding phase)
            for k in range(1, n):
                remaining = n - k
                if remaining >= 1:
                    # Choose pivot row: k rows expand, remaining contract
                    # The split can occur at any of k+1 positions
                    ways = C(k + remaining - 1, remaining - 1)
                    if ways > 0:
                        ans = (ans + ways * up[k][l][r] % MOD * down[remaining][l][r] % MOD) % MOD

    return str(ans) + "\n"
